// Extension property dan extension pada tipe nullable
val String.hurufSaja: String get() = filter { it.isLetter() }
fun String?.ringkas(maks: Int = 10): String =
    when {
        this == null -> "(kosong)"
        length <= maks -> this
        else -> take(maks - 3) + "..."
    }

fun main() {
